24	        String city = request.getCity();
25	        long inCity = ownerRepository.findAll().stream()
26	            .filter(existing -> city == null
27	                ? existing.getCity() == null
28	                : city.equalsIgnoreCase(existing.getCity()))
29	            .count();
30	        if (inCity >= CITY_CAPACITY) {
31	            throw new CityAtCapacityException(city);
