288	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
289	            points += 2;
290	        }
291	        if (getTenureFiscalYears() >= 1) {
292	            points += 3;
293	        }
294	        return points;
295	    }
296	
297	    /**
298	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
299	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
300	     * created owner scores at most 5 points (tenure being the only route to 6), a new
301	     * owner never exceeds level 3.
302	     */
303	    @Transient
304	    public int getMembershipLevel() {
305	        int points = getMembershipPoints();
306	        if (points <= 1) {
307	            return 1;
308	        }
309	        if (points <= 3) {
310	            return 2;
311	        }
312	        if (points <= 5) {
313	            return 3;
314	        }
315	        return 4;
316	    }
317	
318	    /**
319	     * The owner's tenure counted in elapsed fiscal years: the number of fiscal-year
320	     * boundaries (each 1 July) crossed between {@code registrationDate} and today, i.e.
321	     * {@code fiscalYearOf(today) - fiscalYearOf(registrationDate)}. Zero when no
322	     * registration date is set, and zero for an owner registered in the current fiscal
323	     * year, so the tenure point of {@link #getMembershipLevel()} is never earned at
324	     * creation.
325	     */
326	    @Transient
327	    public long getTenureFiscalYears() {
328	        if (this.registrationDate == null) {
329	            return 0;
330	        }
331	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate);
332	    }
333	
334	    /**
335	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, derived from the
336	     * business-day-adjusted {@code registrationDate}. The fiscal year starts on 1 July,
337	     * so a date in July or later belongs to the fiscal year named by its own calendar
338	     * year, and a date in January to June belongs to the fiscal year that started the
339	     * previous 1 July. {@code YY} is the last two digits of that fiscal year. Returns
340	     * {@code null} when no registration date is set.
341	     */
342	    @Transient
343	    public String getFiscalYear() {
344	        if (this.registrationDate == null) {
345	            return null;
346	        }
347	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
348	    }
349	
350	    /**
351	     * The fiscal year (named by the calendar year in which its 1 July start falls) that
352	     * {@code date} belongs to. July onward is the current calendar year; January to June
353	     * belongs to the fiscal year that began the previous 1 July.
354	     */
355	    private static int fiscalYearOf(LocalDate date) {
356	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
357	                ? date.getYear() : date.getYear() - 1;
358	    }
359	
360	    /**
361	     * The owner's canonical region, preferring the postcode over the city.
362	     *
363	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
364	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
365	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
366	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
367	     * backs both the {@code locality} field and the {@code REGION} segment of the
368	     * {@code customerCode}, so the two always agree.
369	     */
370	    @Transient
371	    public String getRegion() {
372	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
373	            int value = Integer.parseInt(this.postcode);
374	            if (value >= 2000 && value <= 2099) {
375	                return "NSW";
376	            }
377	            if (value >= 3000 && value <= 3099) {
378	                return "VIC";
379	            }
380	            if (value >= 4000 && value <= 4099) {
381	                return "QLD";
382	            }
383	        }
384	        if ("Sydney".equals(this.city)) {
385	            return "NSW";
386	        }
387	        if ("Melbourne".equals(this.city)) {
388	            return "VIC";
389	        }
390	        if ("Brisbane".equals(this.city)) {
391	            return "QLD";
392	        }
393	        return "UNKNOWN";
394	    }
395	
396	    /**
397	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
398	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
399	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
400	     */
401	    @Transient
402	    public String getTimezone() {
403	        switch (getRegion()) {
404	            case "NSW":
405	                return "Australia/Sydney";
406	            case "VIC":
407	                return "Australia/Melbourne";
408	            case "QLD":
409	                return "Australia/Brisbane";
410	            default:
411	                return null;
412	        }
413	    }
414	
415	    /**
416	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
417	     * present, otherwise {@code PHONE}.
418	     */
419	    @Transient
420	    public String getContactPreference() {
421	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
422	    }
423	
424	    /**
425	     * The owner's derived duplicate-detection key: the normalized (E.164) telephone,
426	     * the email (or empty when absent) and the {@code householdId} (or empty when
427	     * absent), joined by {@code '|'}. Two owners are duplicates only when their whole
428	     * identity keys are equal.
429	     */
430	    @Transient
431	    public String getIdentityKey() {
432	        String tel = this.telephone == null ? "" : this.telephone;
433	        String mail = this.email == null ? "" : this.email;
434	        String household = this.householdId == null ? "" : this.householdId;
435	        return tel + "|" + mail + "|" + household;
436	    }
437	
438	    protected Set<Pet> getPetsInternal() {
439	        if (this.pets == null) {
440	            this.pets = new HashSet<>();
441	        }
442	        return this.pets;
443	    }
444	
445	    protected void setPetsInternal(Set<Pet> pets) {
446	        this.pets = pets;
447	    }
448	
449	    public List<Pet> getPets() {
450	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
451	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
452	        return Collections.unmodifiableList(sortedPets);
453	    }
454	
455	    public void setPets(List<Pet> pets) {
456	        this.pets = new HashSet<>(pets);
457	    }
458	
459	    public void addPet(Pet pet) {
460	        getPetsInternal().add(pet);
461	        pet.setOwner(this);
462	    }
463	
464	    /**
465	     * Return the Pet with the given name, or null if none found for this Owner.
466	     *
467	     * @param name to test
468	     * @return true if pet name is already in use
469	     */
470	    public Pet getPet(String name) {
471	        return getPet(name, false);
472	    }
473	
474	    /**
475	     * Return the Pet with the given name, or null if none found for this Owner.
476	     *
477	     * @param name to test
478	     * @return true if pet name is already in use
479	     */
480	    public Pet getPet(String name, boolean ignoreNew) {
481	        name = name.toLowerCase();
482	        for (Pet pet : getPetsInternal()) {
483	            if (!ignoreNew || !pet.isNew()) {
484	                String compName = pet.getName();
485	                compName = compName.toLowerCase();
486	                if (compName.equals(name)) {
487	                    return pet;
488	                }
489	            }
490	        }
491	        return null;
492	    }
493	
494	    public Pet getPet(Integer petId) {
495	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
496	    }
497	
498	    @Override
499	    public String toString() {
500	        return new ToStringCreator(this)
501	
502	            .append("id", this.getId())
503	            .append("new", this.isNew())
504	            .append("lastName", this.getLastName())
505	            .append("firstName", this.getFirstName())
506	            .append("address", this.address)
507	            .append("city", this.city)
508	            .append("telephone", this.telephone)
509	            .toString();
510	    }
